// Scheduled jobs for doitforme.
//
// A separate Worker on purpose. The main app is generated by
// @opennextjs/cloudflare, which rewrites .open-next/worker.js on every build —
// adding a `scheduled` handler there means either editing generated output or
// wrapping an entry whose named Durable Object exports change between adapter
// versions. This Worker just makes authenticated HTTP calls to cron routes that
// already exist and already verify CRON_SECRET, so nothing about it can be
// broken by a rebuild of the app.
//
// WHY THE SCHEDULES CHANGED. On Vercel Hobby every cron was capped at once per
// day and was only hour-accurate. auto-release is the one that hurt: a worker
// delivers, the poster has 24h to review, and the release only happens the next
// time the job runs — so a delivery landing just after the daily run waited
// closer to 48h for money the UI had already promised in 24. Cloudflare Cron
// Triggers have no such limit on any plan, so auto-release now runs every 15
// minutes and the 24h in the product copy is finally the truth.
//
// The other two keep their original UTC times so their behaviour is unchanged.

export interface Env {
  /** Origin of the deployed app, no trailing slash. e.g. https://doitforme.in */
  APP_ORIGIN: string;
  /** Must match the CRON_SECRET the app checks. Set with `wrangler secret put`. */
  CRON_SECRET: string;
}

/** cron expression -> the routes it should call. Keep in sync with wrangler.jsonc.
 *
 * One cron trigger can fan out to multiple routes. This is how both Round 1
 * jobs (nudge + send-drain) share one trigger: Cloudflare Workers Free caps at
 * 5 cron triggers per account, we were already at 5 before adding the send
 * drain, and $5/month to raise that cap wasn't worth it when the two routes
 * can run back-to-back on the same tick without contending. Each route checks
 * its own kill switch and no-ops when it has nothing to do, so firing both
 * every 15 minutes is cheap. */
const SCHEDULE: Record<string, string[]> = {
  "*/15 * * * *": ["/api/cron/auto-release"],
  "30 7 * * *": ["/api/cron/nudge-posters"],
  "0 9 * * *": ["/api/cron/process-payouts"],
  // Retention. The notification tables were 79% of a database that had gone 50%
  // over the free tier; capping the fan-out fixed the inflow, this is the
  // outflow. 03:30 UTC (09:00 IST) is the quietest hour.
  "30 3 * * *": ["/api/cron/prune-data"],
  // Inner Circle Round 1: two routes sharing one trigger.
  //   - nudge: fires reminder emails and flips expired candidates
  //   - send:  drains the pending-invite queue when ROUND1_AUTOSEND=1
  // Offset by 5 minutes from auto-release so the two don't contend for Worker
  // CPU on the quarter hour.
  "5,20,35,50 * * * *": [
    "/api/cron/inner-circle-round1-nudge",
    "/api/cron/inner-circle-round1-send",
  ],
};

async function runJob(env: Env, path: string): Promise<void> {
  const url = `${env.APP_ORIGIN}${path}`;
  const started = Date.now();

  try {
    const res = await fetch(url, {
      method: "GET",
      headers: {
        "x-cron-secret": env.CRON_SECRET,
        "user-agent": "doitforme-cron/1.0",
      },
    });

    const body = await res.text();
    const ms = Date.now() - started;

    if (!res.ok) {
      // Logged, not thrown: a failing job should not retry in a tight loop, and
      // the next tick is at most 15 minutes away.
      console.error(`[cron] ${path} -> ${res.status} in ${ms}ms :: ${body.slice(0, 300)}`);
      return;
    }
    console.log(`[cron] ${path} -> ${res.status} in ${ms}ms :: ${body.slice(0, 300)}`);
  } catch (err) {
    console.error(`[cron] ${path} threw after ${Date.now() - started}ms:`, err);
  }
}

export default {
  async scheduled(event: ScheduledController, env: Env, ctx: ExecutionContext): Promise<void> {
    const paths = SCHEDULE[event.cron];
    if (!paths || paths.length === 0) {
      console.error(`[cron] no routes mapped for schedule "${event.cron}"`);
      return;
    }
    // Fan out to every route on this trigger. Promise.all rather than sequential
    // keeps total CPU in-budget on ticks where both Round 1 routes fire, since
    // each spends most of its time waiting on D1/HTTP, not on CPU.
    ctx.waitUntil(Promise.all(paths.map((p) => runJob(env, p))));
  },

  // Manual trigger, so a job can be run on demand without waiting for its slot.
  // Requires the same secret the app does, so it is no weaker than the endpoint
  // it calls. Anything else 404s rather than describing the surface.
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname !== "/__run") return new Response("Not found", { status: 404 });

    if (request.headers.get("x-cron-secret") !== env.CRON_SECRET) {
      return new Response("Unauthorized", { status: 401 });
    }

    const job = url.searchParams.get("job");
    const allPaths = Object.values(SCHEDULE).flat();
    const path = allPaths.find((p) => p.endsWith(`/${job}`));
    if (!path) {
      return new Response(
        `Unknown job. Try one of: ${allPaths.map((p) => p.split("/").pop()).join(", ")}`,
        { status: 400 }
      );
    }

    await runJob(env, path);
    return new Response(`ran ${path}\n`);
  },
};
